parameters.jsCode:
// Parse AI response and combine with original form data
try {
  const aiResponse = JSON.parse($input.first().json.message.content);
  const formData = $('Webhook').first().json;

  return [{ json: {
    ...formData,
    classification: aiResponse.classification,
    reason: aiResponse.reason,
    timestamp: new Date().toISOString()
  } }];
} catch (error) {
  // If AI response parsing fails, treat as spam with error note
  const formData = $('Webhook').first().json;
  return [{ json: {
    ...formData,
    classification: 'SPAM',
    reason: `AI response parsing failed: ${error.message}`,
    timestamp: new Date().toISOString()
  } }];
}
